replacements.after:
/* Keep enlarged labels inside real controls; wrap samples rather than clip text. */
@media(max-width:700px){
 .materials button{flex:1 1 8em;min-width:0;min-height:56px;grid-template-columns:40px minmax(0,1fr);overflow-wrap:anywhere}
 .materials button b{min-width:0}
 .heat-units{flex-wrap:wrap;align-items:stretch}
 .heat-unit{font-size:13px;flex:1 1 9em;max-width:none;min-width:0;overflow-wrap:anywhere}
 .heat-apparatus{display:flex;justify-content:center;align-items:end;height:auto;min-height:104px;padding:62px 0 0}
 .watch-sample{left:calc(50% - 27px);width:54px}
 .heater-plate{left:calc(50% - 30px);top:53px;bottom:auto;width:60px}
 .heat-feed{left:calc(50% - 21px);top:20px;bottom:auto}
 .watch-thermometer{right:3px;top:3px}
 .heat-apparatus>strong{margin:0;font-size:21px;line-height:1.3;white-space:normal}
 .heat-apparatus>strong small{font-size:14px}
 .watch-power{overflow-wrap:anywhere}
}
